{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLs enabled",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "MEDIUM",
      "explanation": "The resource `aws_s3_bucket_public_access_block.document_storage` is missing the `block_public_acls` argument. Without this setting explicitly set to true, the default behavior (false) allows public ACLs to be applied to objects in the bucket, potentially exposing data."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket = aws_s3_bucket.document_storage.id\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n  block_public_acls       = true\n}",
  "fix_summary": "Added the missing `block_public_acls = true` argument to the `aws_s3_bucket_public_access_block` resource to ensure public ACLs are blocked, satisfying Checkov rule CKV_AWS_53."
}
